<script setup lang="ts">import{useInventoryChoice}from'./use-inventory-choice';const props=defineProps<{kind:'materials'|'suppliers';account:any;clinicId:string;formKey:number;disabled:boolean;read:(path:string,signal:AbortSignal)=>Promise<any>}>(),emit=defineEmits(['selected']);const model=useInventoryChoice({context:()=>JSON.stringify([props.account?.accountId,props.account?.employeeId,props.clinicId,props.formKey]),kind:props.kind,clinic:()=>props.clinicId,read:(p,s)=>props.read(p,s),selected:v=>emit('selected',v)});const title=props.kind==='materials'?'物资':'供应商';</script>
<template><section class="inventory-choice" :aria-label="title+'查找选择'"><strong>{{title}}</strong><template v-if="!model.selection.value"><label>{{title}}查找线索<input v-model="model.search.value" :disabled="disabled" maxlength="100" :placeholder="kind==='materials'?'输入名称、分类或规格（至少2字）':'输入供应商名称（至少2字）'" @keydown.enter.prevent="!disabled&&model.load()"/></label><button type="button" class="b-button outline small" :disabled="disabled||model.loading.value" @click="model.load()">查找{{title}}</button><div v-if="model.error.value" class="b-alert error" role="alert">{{model.error.value}}</div><p class="b-help">只列可供新选择的{{title}}。请核对后点击选择，列表筛选不影响这里的查找。</p><div v-for="item in model.items.value" :key="item.id" class="inventory-choice-row"><div><strong>{{item.name}}</strong><p v-if="kind==='materials'">{{item.classification}} · {{item.specification||'规格未提供'}} · {{item.unit}}</p><small>编号 {{item.id.slice(0,8).toUpperCase()}}</small></div><button type="button" class="f-text" :disabled="disabled||model.loading.value" :aria-label="'选择 '+item.name" @click="model.choose(item)">选择</button></div><p v-if="model.total.value||model.items.value.length" class="b-help">已显示 {{model.items.value.length}} / {{model.total.value}} 项</p><p v-else-if="model.search.value.trim().length>=2&&!model.loading.value" class="b-help">查找后在此核对候选；没有匹配时可补充或修改线索。</p><button v-if="model.next.value" type="button" class="b-button outline small" :disabled="disabled||model.loading.value" @click="model.load(true)">继续加载{{title}}候选</button></template><template v-else><p>已选择：<strong>{{model.selection.value.name}}</strong></p><p v-if="kind==='materials'">{{model.selection.value.classification}} · {{model.selection.value.specification||'规格未提供'}} · {{model.selection.value.unit}}</p><button type="button" class="f-text" :disabled="disabled" @click="model.clear()">重新选择{{title}}</button></template></section></template>
<style scoped>.inventory-choice{padding:16px;border:1px solid #dce5dc;border-radius:10px;margin:16px 0;min-width:0}.inventory-choice>label{display:flex;flex-direction:column;gap:8px;margin:12px 0;min-width:0}.inventory-choice input{box-sizing:border-box;width:100%;min-width:0}.inventory-choice-row{display:flex;gap:14px;align-items:center;justify-content:space-between;border-top:1px solid #e2e8df;padding:14px 0;overflow-wrap:anywhere}.inventory-choice-row>div{min-width:0}.inventory-choice-row p,.inventory-choice>p{font-size:14px;line-height:1.7}.inventory-choice-row small{color:#6e7e69}.inventory-choice-row button{flex-shrink:0}</style>
